/// <summary>
/// PricingAttribute of table <c>InventTable</c> field BOMCalcGroupId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableBOMCalcGroupId extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, BOMCalcGroupId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventTable inventTable;
    while select BOMCalcGroupId from inventTable
        group by BOMCalcGroupId
    {
        ret.add(inventTable.BOMCalcGroupId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, BOMCalcGroupId));
    qbr.value(queryValue(_value));
}
